def mat(frame, cushion=None, metal='tekko', outline=('sumi',-1)):
    c=cushion or frame; sh=0 if cushion else 1
    fr=lambda t:(frame,t)
    return {'O':outline,'D':fr(-2),'d':fr(-1),'m':fr(0),'l':fr(1),'H':fr(2),
            'C':(c,-1+sh),'n':(c,-2+sh),'c':(c,0+sh),'e':(c,1+sh),'E':(c,2+sh),
            'T':(metal,-1),'t':(metal,0),'M':(metal,1),'W':(metal,3)}
def img(rows,M,H=16):
    im=Image.new('RGBA',(16,H)); oy=H-len(rows)
    for y,r in enumerate(rows):
        assert len(r)==16,(y,r)
        for x,ch in enumerate(r):
            if ch!='.': im.putpixel((x,oy+y),(*rgb(K(*M[ch])),255))
    return im
def outline(im, col):
    W,H=im.size; a=im.load(); S={(x,y) for y in range(H) for x in range(W) if a[x,y][3]}
    for (x,y) in S:
        if any((x+dx,y+dy) not in S for dx,dy in ((1,0),(-1,0),(0,1),(0,-1))): im.putpixel((x,y),(*rgb(col),255))
    return im
def sofa(m='kon'):
    im=Image.new('RGBA',(32,32)); P=lambda x,y,t: im.putpixel((x,y),(*rgb(K(m,t)),255))
    for y in range(5,16):                                  # back: lit rim 2 rows, face mid, crease
        for x in range(3,29):
            t=2 if y in (6,7) else 1
            if x==16 and y>7: t=-1                          # seam between two back cushions
            if y==15: t=-1
            P(x,y,t)
    for y in range(11,29):                                 # arms: lit top cap, mid front
        for x in list(range(0,5))+list(range(27,32)):
            t=(2 if x in (1,2,28,29) and y<=12 else 1) if y<=23 else (0 if x<5 else -1)
            P(x,y,t)
    for y in range(16,24):                                 # seat: brightest upper plane, mid lower, lip
        for x in range(5,27):
            t=2 if y<=18 else 1 if y<=21 else 0
            if x==16 and y<=21: t=0
            P(x,y,t)
    for y in range(24,28):
        for x in range(5,27): P(x,y,0 if y==24 else -1)
    for x in range(0,32): P(x,28,-2); P(x,27,-2) if not (5<=x<=26) else None
    for y in range(13,28): P(4,y,-1); P(27,y,-1)
    outline(im,K(m,-2))
    for x in (2,3,28,29):
        for y in (29,30): im.putpixel((x,y),(*rgb(K('ita',-3 if (y==30 or x in (3,29)) else -1)),255))
    return im
def table(m='ita'):
    im=Image.new('RGBA',(32,16)); P=lambda x,y,t: im.putpixel((x,y),(*rgb(K(m,t)),255))
    for y in range(0,10):
        for x in range(0,32):
            t=1 if y>=2 else 2
            if y==9: t=0
            if x>=29: t-=1
            if y in (5,) and (x//8)%2==0 and 1<=x<=30: t=0       # staggered plank seams
            if y in (3,7) and (x//8)%2==1 and 1<=x<=30: t=0
            P(x,y,t)
    for x in range(0,32): P(x,10,0); P(x,11,-1)
    for y in range(12,16):
        for x,t in ((1,0),(2,1),(3,-1),(4,0),(27,0),(28,1),(29,-1),(30,0)): P(x,y,t)
    outline(im,K('sumi',-1))
    return im
if __name__=='__main__':
    O='/tmp/seats34/study2/out/'
    dining=mat('ki'); office=mat('kon')
    S={'dining chair S':img(T['chairS'],dining),'dining chair N':img(T['chairN'],dining),'dining chair E':img(T['chairE'],dining),'dining chair W':img(T['chairW'],dining),
       'office chair S':img(T['officeS'],office),'office chair N':img(T['officeN'],office),'cafe stool':img(T['stool'],mat('ita')),'sofa S 2x2':sofa()}
    st=Image.new('RGBA',(32,43))
    for x in (0,16): st.alpha_composite(S['dining chair S'],(x,0))
    st.alpha_composite(table(),(0,14))
    for x in (0,16): st.alpha_composite(S['dining chair N'],(x,27)); S['table and chairs set']=st
